content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #cbd5e1;
  --border-radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --transition: all 0.2s ease-in-out;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  padding: 16px;
}

.app-container {
  max-width: 800px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding-bottom: 40px;
}

.header {
  text-align: center;
  padding: 12px 0;
}

.title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 4px;
}

.converter-card {
  background-color: var(--card-bg);
  border-radius: var(--border-radius);
  padding: 24px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.input-group label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
}

.input,
.select {
  width: 100%;
  padding: 12px 16px;
  font-size: 1rem;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background-color: #fff;
  color: var(--text-main);
  transition: var(--transition);
  box-shadow: none;
}

.input:focus,
.select:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.result-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 8px;
}

.result-card {
  background-color: #f1f5f9;
  border-radius: 8px;
  padding: 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 1.1rem;
  font-weight: 600;
}

.result-value {
  color: var(--primary-color);
  font-size: 1.25rem;
}

.table-container {
  background-color: var(--card-bg);
  border-radius: var(--border-radius);
  padding: 20px;
  box-shadow: var(--shadow);
  overflow-x: auto;
}

.conversion-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.95rem;
}

.conversion-table th,
.conversion-table td {
  padding: 12px 16px;
  border-bottom: 1px solid #e2e8f0;
}

.conversion-table th {
  background-color: #f8fafc;
  color: var(--text-muted);
  font-weight: 600;
}

.conversion-table tr:hover {
  background-color: #f8fafc;
}

.history-section {
  background-color: var(--card-bg);
  border-radius: var(--border-radius);
  padding: 20px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.history-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.history-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 200px;
  overflow-y: auto;
}

.history-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px;
  background-color: #f8fafc;
  border-radius: 8px;
  font-size: 0.9rem;
  border: 1px solid #e2e8f0;
}

.btn-clear {
  background-color: #ef4444;
  color: white;
  border: none;
  padding: 6px 12px;
  font-size: 0.85rem;
  font-weight: 600;
  border-radius: 6px;
  cursor: pointer;
  transition: var(--transition);
}

.btn-clear:hover {
  background-color: #dc2626;
}

@media (max-width: 480px) {
  body {
    padding: 8px;
  }

  .converter-card,
  .table-container,
  .history-section {
    padding: 16px;
  }

  .title {
    font-size: 1.5rem;
  }
}

export type Unit = 'mm' | 'cm' | 'm' | 'km' | 'inch' | 'ft';

export interface ConversionRecord {
  id: string;
  value: number;
  fromUnit: Unit;
  toUnit: Unit;
  result: number;
  timestamp: string;
}

import { useState, useEffect } from 'react';
import { Unit } from '../types';

interface UnitConverterProps {
  onAddHistory: (value: number, fromUnit: Unit, toUnit: Unit, result: number) => void;
}

const UNIT_LABELS: Record<Unit, string> = {
  mm: 'ミリメートル (mm)',
  cm: 'センチメートル (cm)',
  m: 'メートル (m)',
  km: 'キロメートル (km)',
  inch: 'インチ (in)',
  ft: 'フィート (ft)',
};

// 全てミリメートルを基準とした換算レート
const TO_MM_RATES: Record<Unit, number> = {
  mm: 1,
  cm: 10,
  m: 1000,
  km: 1000000,
  inch: 25.4,
  ft: 304.8,
};

export default function UnitConverter({ onAddHistory }: UnitConverterProps) {
  const [value, setValue] = useState<number | ''>(1);
  const [fromUnit, setFromUnit] = useState<Unit>('m');
  const [toUnit, setToUnit] = useState<Unit>('cm');

  const convert = (val: number, from: Unit, to: Unit): number => {
    const inMm = val * TO_MM_RATES[from];
    const result = inMm / TO_MM_RATES[to];
    return Number(result.toFixed(6));
  };

  const numericValue = typeof value === 'number' ? value : 0;
  const currentResult = convert(numericValue, fromUnit, toUnit);

  useEffect(() => {
    if (typeof value === 'number' && !isNaN(value)) {
      onAddHistory(value, fromUnit, toUnit, currentResult);
    }
  }, [value, fromUnit, toUnit]);

  return (
    <div className="converter-card">
      <div className="input-group">
        <label>変換する値</label>
        <input
          type="number"
          className="input"
          value={value}
          onChange={(e) => {
            const val = e.target.value === '' ? '' : parseFloat(e.target.value);
            setValue(isNaN(val) ? '' : val);
          }}
          placeholder="数値を入力"
        />
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
        <div className="input-group">
          <label>変換元</label>
          <select
            className="select"
            value={fromUnit}
            onChange={(e) => setFromUnit(e.target.value as Unit)}
          >
            {(Object.keys(UNIT_LABELS) as Unit[]).map((u) => (
              <option key={u} value={u}>
                {UNIT_LABELS[u]}
              </option>
            ))}
          </select>
        </div>

        <div className="input-group">
          <label>変換先</label>
          <select
            className="select"
            value={toUnit}
            onChange={(e) => setToUnit(e.target.value as Unit)}
          >
            {(Object.keys(UNIT_LABELS) as Unit[]).map((u) => (
              <option key={u} value={u}>
                {UNIT_LABELS[u]}
              </option>
            ))}
          </select>
        </div>
      </div>

      <div className="result-section">
        <div className="result-card">
          <span>変換結果</span>
          <span className="result-value">
            {currentResult} {toUnit}
          </span>
        </div>
      </div>
    </div>
  );
}

import { ConversionRecord } from '../types';

interface ConversionHistoryProps {
  history?: ConversionRecord[];
  onClearHistory?: () => void;
}

export default function ConversionHistory({ history = [], onClearHistory }: ConversionHistoryProps) {
  if (history.length === 0) {
    return (
      <div className="history-section">
        <div className="history-header">
          <h3 style={{ fontSize: '1.1rem', fontWeight: 600 }}>変換履歴</h3>
        </div>
        <p style={{ color: 'var(--text-muted)', fontSize: '0.9rem' }}>履歴はまだありません</p>
      </div>
    );
  }

  return (
    <div className="history-section">
      <div className="history-header">
        <h3 style={{ fontSize: '1.1rem', fontWeight: 600 }}>変換履歴</h3>
        <button className="btn-clear" onClick={onClearHistory}>
          履歴をクリア
        </button>
      </div>
      <div className="history-list">
        {history.map((item) => (
          <div key={item.id} className="history-item">
            <span>
              {item.value} {item.fromUnit} → <strong>{item.result} {item.toUnit}</strong>
            </span>
            <span style={{ color: 'var(--text-muted)', fontSize: '0.8rem' }}>{item.timestamp}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { ConversionRecord, Unit } from './types';
import UnitConverter from './components/UnitConverter';
import ConversionTable from './components/ConversionTable';
import ConversionHistory from './components/ConversionHistory';

export default function App() {
  const [history, setHistory] = useState<ConversionRecord[]>([]);

  const handleAddHistory = (value: number, fromUnit: Unit, toUnit: Unit, result: number) => {
    const newItem: ConversionRecord = {
      id: `${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
      value,
      fromUnit,
      toUnit,
      result,
      timestamp: new Date().toLocaleTimeString(),
    };

    setHistory((prev) => {
      // 直前の履歴と同じ内容なら重複追加を防ぐ（数値や単位が変わったときだけ追加）
      const last = prev[0];
      if (
        last &&
        last.value === value &&
        last.fromUnit === fromUnit &&
        last.toUnit === toUnit &&
        last.result === result
      ) {
        return prev;
      }
      return [newItem, ...prev].slice(0, 20); // 最大20件
    });
  };

  const handleClearHistory = () => {
    setHistory([]);
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">長さ単位変換ツール</h1>
        <p style={{ color: 'var(--text-muted)' }}>ミリ・センチ・メートル・インチ等の単位をリアルタイム変換</p>
      </header>

      <UnitConverter onAddHistory={handleAddHistory} />

      <ConversionTable />

      <ConversionHistory history={history} onClearHistory={handleClearHistory} />
    </div>
  );
}
